cd /testbed && python3 - <<'PY'
import os, socket, subprocess, tempfile, time
cli='/testbed/src/valkey-cli'
def port():
    with socket.socket() as s:
        s.bind(('127.0.0.1',0)); return s.getsockname()[1]
def cmd(p,*args):
    return subprocess.run([cli,'-p',str(p),*args], capture_output=True,text=True,timeout=5)
def ready(p, proc):
    for _ in range(600):
        if cmd(p,'PING').stdout.strip()=='PONG': return True
        if proc.poll() is not None: return False
        time.sleep(.1)
    return False
with tempfile.TemporaryDirectory(prefix='acl-peeky-',dir='/testbed/tests/tmp') as d:
    os.environ['PEEKY_STATE_DIR']=os.path.join(d,'peeky-state')
    acl=os.path.join(d,'valkey.acl')
    with open(acl,'w') as f: f.write('user foo on #551a821992d8592d71c26a4989e26ce1d39e90ba3c20e3eaf99eed4a2e64251f +@all ~* resetchannels &*\n')
    pp,rp=port(),port()
    primary=subprocess.Popen(['/testbed/src/valkey-server','--port',str(pp),'--dir',d,'--save','','--appendonly','no','--logfile',os.path.join(d,'primary.log')],stdout=subprocess.DEVNULL,stderr=subprocess.STDOUT)
    session=None; request=None
    def peek(*args):
        invocation=['peeky','session',*args]
        print('$ '+' '.join(invocation),flush=True)
        r=subprocess.run(invocation,capture_output=True,text=True,timeout=45)
        print(r.stdout,r.stderr,flush=True)
        return r
    try:
        assert ready(pp,primary)
        invocation=['peeky','session','start','.','--binary','src/valkey-server','--at','src/acl.c:2382','--name','acl-replica','--timeout','30','--','--port',str(rp),'--replicaof','127.0.0.1',str(pp),'--aclfile',acl,'--dir',d,'--save','','--appendonly','no','--logfile',os.path.join(d,'replica.log')]
        print('$ '+' '.join(invocation),flush=True)
        session=subprocess.Popen(invocation,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
        if not ready(rp,session):
            out,err=session.communicate(timeout=40); print(out,err,flush=True)
        else:
            for _ in range(200):
                if 'master_link_status:up' in cmd(rp,'INFO','replication').stdout: break
                time.sleep(.05)
            else: raise RuntimeError('replication did not connect')
            request=subprocess.Popen([cli,'-p',str(rp),'ACL','LOAD'],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True)
            out,err=session.communicate(timeout=40); print(out,err,flush=True)
            peek('get','original','c.user','c.flag.primary','c.id','--name','acl-replica')
            peek('step','--name','acl-replica')
            peek('report','--name','acl-replica')
    finally:
        peek('close','--name','acl-replica')
        for p in (request,session,primary):
            if p is not None and p.poll() is None: p.terminate()
        for p in (request,session,primary):
            if p is not None:
                try: p.wait(timeout=5)
                except subprocess.TimeoutExpired: p.kill(); p.wait()
PY

